create table if not exists public.timeline_daw_normalization_support_audit_chain(id text primary key,owner_id uuid not null references auth.users(id) on delete cascade,session_id text not null,event_type text not null check(event_type in('export','revocation','repair')),subject_id text not null,previous_hash text,chain_hash text not null unique,event_checksum text not null,created_at timestamptz not null default now());alter table public.timeline_daw_normalization_support_audit_chain enable row level security;create policy timeline_daw_normalization_support_audit_chain_owner on public.timeline_daw_normalization_support_audit_chain for select to authenticated using(owner_id=auth.uid());create policy timeline_daw_normalization_support_audit_chain_insert on public.timeline_daw_normalization_support_audit_chain for insert to authenticated with check(owner_id=auth.uid());create index if not exists timeline_daw_normalization_support_audit_chain_order on public.timeline_daw_normalization_support_audit_chain(owner_id,session_id,created_at desc);create table if not exists public.timeline_daw_normalization_support_audit_repairs(id text primary key,owner_id uuid not null references auth.users(id) on delete cascade,session_id text not null,case_id text,base_checksum text not null,plan_checksum text not null,before_findings jsonb not null,after_findings jsonb not null,actions jsonb not null,provenance text not null,chain_hash text not null,created_at timestamptz not null default now());alter table public.timeline_daw_normalization_support_audit_repairs enable row level security;create policy timeline_daw_normalization_support_audit_repairs_owner on public.timeline_daw_normalization_support_audit_repairs for select to authenticated using(owner_id=auth.uid());create policy timeline_daw_normalization_support_audit_repairs_insert on public.timeline_daw_normalization_support_audit_repairs for insert to authenticated with check(owner_id=auth.uid());
